function.arguments:
{"script": "#!/bin/bash
python3 << 'EOF'
import FreeCAD

# Open the saved document
doc = FreeCAD.open("/home/user/Unnamed.FCStd")

shell_obj = doc.getObject("Shell")
shape = shell_obj.Shape

print(f"Shell has {len(shape.Faces)} faces\n")

for i, face in enumerate(shape.Faces):
    bbox = face.BoundBox
    center = face.CenterOfMass
    area = face.Area
    num_wires = len(face.Wires)

    # Determine face type based on orientation
    if abs(bbox.ZMax - bbox.ZMin) < 0.01:
        if abs(bbox.ZMax - 0) < 0.01:
            face_type = "Bottom"
        elif abs(bbox.ZMax - 18) < 0.01:
            face_type = f"Top (wires={num_wires})"
        else:
            face_type = "Horizontal"
    elif abs(bbox.XMax - bbox.XMin) < 0.01:
        if abs(bbox.XMin - 0) < 0.01:
            face_type = "Left wall"
        elif abs(bbox.XMax - 38) < 0.01:
            face_type = "Right wall"
        else:
            face_type = "Vertical X"
    elif abs(bbox.YMax - bbox.YMin) < 0.01:
        if abs(bbox.YMin - 0) < 0.01:
            face_type = "Front wall"
        elif abs(bbox.YMax - 26) < 0.01:
            face_type = "Back wall"
        else:
            face_type = "Vertical Y"
    else:
        face_type = "Unknown"

    print(f"Face {i}: {face_type}, Center=({center.x:.1f}, {center.y:.1f}, {center.z:.1f}), Area={area:.1f}")

FreeCAD.closeDocument(doc.Name)
EOF", "timeout_seconds": 60}
